function insertAfterKey(
    locText: string,
    baseKey: string,
    newLines: string[]
): string {
    if (newLines.length === 0) return locText;

    const tokensMatch = locText.match(/"Tokens"\s*\{([\s\S]*?)\n\}/);
    if (!tokensMatch) return locText;

    const body = tokensMatch[1];
    const lines = body.split("\n");

    const idx = lines.findIndex(l => l.includes(`"${baseKey}"`));
    if (idx === -1) return locText;

    const result = [
        ...lines.slice(0, idx + 1),
        ...newLines,
        ...lines.slice(idx + 1),
    ];

    const start =
        tokensMatch.index! + tokensMatch[0].indexOf("{") + 1;
    const end = start + body.length;

    return locText.slice(0, start) + result.join("\n") + locText.slice(end);
}


export function expandLocalizationByLevel(params: {
    rawItemOrder: string[];
    rawItems: KVObject;
    statsItems: KVObject;
    locKV: KVObject;
    locText: string;
    insertIndexRef: { value: number };
    insertLocalizationByIndex: Function;
    buildTooltipValueForField: Function;
    maxLevelMap: Record<string, number>;
}): string {
    const {
        rawItemOrder,
        rawItems,
        statsItems,
        locKV,
        insertIndexRef,
        insertLocalizationByIndex,
        buildTooltipValueForField,
        maxLevelMap,
    } = params;

