            const baseKey =
                `DOTA_Tooltip_Ability_${itemName}${suf}`;

            const m = locText.match(
                new RegExp(`"${baseKey}"\\s+"([^"]*)"`)
            );
            if (!m) continue;

            const value = m[1];
            const newLines: string[] = [];

            for (let lvl = 1; lvl <= maxLevel; lvl++) {
                const newKey =
                    `DOTA_Tooltip_Ability_${itemName}_${lvl}${suf}`;

                if (locText.includes(`"${newKey}"`)) continue;

